// 共享候选：提名不授予职位，本人到任实际调用原Office账，再由原提交尾绑定真实结果。
#include "political_subordinate_appointment_world.hpp"
#include "world_bundle.hpp"
namespace hanmo::resident {namespace {
Status available(const WorldBundle& w){return w.catalog->political_subordinate_appointments&&w.political_subordinate_appointments&&w.catalog->political_successions&&w.political_successions&&w.politics_enabled()&&w.catalog->organization&&w.catalog->organization->enabled&&w.family_life_enabled()&&w.catalog->common&&w.catalog->family?common_success():common_failure("PoliticalSubordinateAppointmentProfileRequired");}
// 成功效果必须精确对上本次补任事实，到任另带同次唯一原Organization变更。
bool actual_result(const CommitResult& r,const StableId& source,const StableId& office){if(!r.ok||!r.details)return false;const auto* e=std::get_if<PoliticsEffects>(&r.details->data);std::vector<StableId> ids{source};if(!office.empty())ids.push_back(office);return e&&valid_political_subordinate_appointment_effect(r.kind,*e)&&e->fact_ids==ids;}
Status player(const WorldBundle& w,const StableId& actor,const PoliticalSubordinateAppointmentCommand& c){auto v=command_common_guard(w,actor,political_subordinate_appointment_command_kind(c));if(!v.ok)return v;return actor==w.common.state().metadata.player_actor_id?common_success():common_failure("PoliticalSubordinateAppointmentPlayerCommandRequired");}
}
PoliticalSubordinateAppointmentWorldAccess::PoliticalSubordinateAppointmentWorldAccess(const WorldBundle& w):world_(w),military_(w.political_takeover_enabled()?std::optional<MilitaryAccess>{w.services.military_access()}:std::nullopt),occupations_(w.political_takeover_enabled()?std::optional<PoliticalSuccessionOccupationContext>{PoliticalSuccessionOccupationContext{w.political_takeover,*w.catalog->political_takeover,w.military,*w.catalog->military,*military_}}:std::nullopt),territory_{w.common,w.politics,*w.catalog->politics,*w.catalog->political_successions,occupations_?&*occupations_:nullptr},qualification_(w.common,*w.political_subordinate_appointments,{*w.catalog->common,*w.catalog->family,w.family,w.family_birth_enabled()?&w.family_birth:nullptr}),rules_{w.common,*w.catalog->common,w.politics,*w.catalog->politics,w.organization,*w.catalog->organization,w.local_economy,w.services,*w.catalog->political_successions,*w.catalog->political_subordinate_appointments,*w.political_subordinate_appointments,w.family_death_read(),[this](const PoliticalSubordinateAppointmentPolicy& p,Integer tick,const StableId& fact){return validate_political_subordinate_appointment_seats(territory_,p,tick,fact);},[&w](Integer tick,const StableId& fact){return read_political_subordinate_appointment_player_before_fact(w.common,w.family,w.family_legacy_enabled()?&w.family_legacy:nullptr,tick,fact);},&qualification_,w.catalog->political_subordinate_appointment_intents.get(),[&w](const StableId& id)->const PoliticalCareerPolicy*{if(!w.catalog->director)return nullptr;const auto* policy=w.catalog->director->dynamic_subjects?w.catalog->director->policies.find(id):w.catalog->director->subjects.find(id);return policy&&policy->political_career&&std::find(policy->templates.begin(),policy->templates.end(),DirectorTemplate::political_career)!=policy->templates.end()?&*policy->political_career:nullptr;},nullptr}{}
Outcome<std::unique_ptr<PoliticalSubordinateAppointmentWorldAccess>> PoliticalSubordinateAppointmentWorldAccess::create(const WorldBundle& w){auto v=available(w);if(!v.ok)return {false,{},v.error};return {true,std::unique_ptr<PoliticalSubordinateAppointmentWorldAccess>{new PoliticalSubordinateAppointmentWorldAccess(w)},{}};}
// 原Organization、原政治、完整Family/Creation/Birth/Bio/Legacy和首职全史之后必验来源及永久真实结果。
Status preview_political_subordinate_legacy_world(const WorldBundle& w,const PoliticsCommand& command){if(!w.catalog->political_subordinate_appointments)return common_success();auto holder=PoliticalSubordinateAppointmentWorldAccess::create(w);return holder.ok?preview_political_subordinate_legacy_command(holder.value->context(),command):Status{false,{},holder.error};}
Status validate_political_subordinate_appointment_world(const WorldBundle& w){auto v=validate_political_subordinate_appointment_layout(w.common,w.catalog->identity.module_versions,w.political_subordinate_appointments?&*w.political_subordinate_appointments:nullptr);if(!v.ok)return v;if(bool(w.catalog->political_subordinate_appointments)!=w.political_subordinate_appointments.has_value())return common_failure("PoliticalSubordinateAppointmentProfileMismatch");const bool intent_marker=std::find(w.catalog->identity.module_versions.begin(),w.catalog->identity.module_versions.end(),std::make_pair(StableId{political_subordinate_appointment_intents_module},StableId{"1"}))!=w.catalog->identity.module_versions.end();if(intent_marker!=bool(w.catalog->political_subordinate_appointment_intents)||(w.catalog->director&&w.catalog->director->subordinate_appointments!=intent_marker))return common_failure("PoliticalSubordinateIntentProfileMismatch");if(!w.catalog->political_subordinate_appointments)return common_success();auto read=PoliticalSubordinateAppointmentWorldAccess::create(w);if(!read.ok)return {false,{},read.error};v=validate_political_subordinate_appointments(read.value->context());return v.ok?validate_political_subordinate_appointment_player_results(w.common,*w.political_subordinate_appointments,actual_result):v;}
Outcome<PoliticalSubordinateAppointmentQuote> prepare_political_subordinate_appointment_world(const WorldBundle& w,const StableId& actor,const PoliticalSubordinateAppointmentCommand& c){auto v=player(w,actor,c);if(!v.ok)return {false,{},v.error};auto read=PoliticalSubordinateAppointmentWorldAccess::create(w);return read.ok?preview_political_subordinate_appointment(read.value->context(),actor,c):Outcome<PoliticalSubordinateAppointmentQuote>{false,{},read.error};}
Outcome<PoliticsEffects> commit_political_subordinate_appointment_world(WorldBundle& w,const StableId& actor,const PoliticalSubordinateAppointmentCommand& c,const PoliticalSubordinateAppointmentQuote& q){auto v=player(w,actor,c);if(!v.ok)return {false,{},v.error};auto read=PoliticalSubordinateAppointmentWorldAccess::create(w);if(!read.ok)return {false,{},read.error};return apply_political_subordinate_appointment_business_in_candidate(w.common,w.organization,*w.political_subordinate_appointments,read.value->context(),actor,c,q);}
Outcome<BoundaryValue> query_political_subordinate_appointment_world(const WorldBundle& w,const StableId& place,Integer cursor){auto read=PoliticalSubordinateAppointmentWorldAccess::create(w);return read.ok?query_political_subordinate_appointments(read.value->context(),place,cursor):Outcome<BoundaryValue>{false,{},read.error};}
Status bind_political_subordinate_appointment_result_world(WorldBundle& w,const StableId& source,const StableId& actor,Integer request,const CommitResult& r){if(!w.catalog->political_subordinate_appointments||!w.political_subordinate_appointments||source.empty()||!is_political_subordinate_appointment_command(r.kind))return common_failure("PoliticalSubordinateAppointmentNewSourceRequired");return bind_political_subordinate_appointment_player_result(w.common,*w.political_subordinate_appointments,source,actor,request,r,actual_result);}
}
